INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q44732', 'Battle of the Golden Spurs', 'The Battle of the Golden Spurs (Dutch: Guldensporenslag; French: Bataille des éperons d''or) or Battle of Courtrai was a military confrontation between the royal army of France and rebellious forces of the County of Flanders on 11 July 1302 during the 1297–1305 Franco-Flemish War. It took place near the town of Kortrijk in modern-day Belgium and resulted in an unexpected victory for the Flemish.', 1302, 7, 11, NULL, NULL, NULL, 'day', '11 July 1302', 70, 'https://en.wikipedia.org/wiki/Battle_of_the_Golden_Spurs'),
  ('Q700027', 'Union of Arras', 'The Union of Arras (Dutch: Unie van Atrecht, French: Union d''Arras, Spanish: Unión de Arrás) was an alliance between the County of Artois, the County of Hainaut and the city of Douai in the Habsburg Netherlands in early 1579 during the Eighty Years'' War. Dissatisfied with the religious policies of rebel leader Prince of Orange and the States General of the Netherlands, and especially the rise of the radical Calvinist Republic of Ghent since October 1577, they signed a declaration on 6 January 1579 about their intent to offer a vigorous defense of the Catholic religion against what they saw…', 1579, 1, 6, NULL, NULL, NULL, 'day', '6 January 1579', 64, 'https://en.wikipedia.org/wiki/Union_of_Arras'),
  ('Q697823', 'Fall of Antwerp', 'The fall of Antwerp (Dutch: val van Antwerpen [vɑl vɑn ˈɑntʋɛrpə(n)]) on 17 August 1585 took place during the Eighty Years'' War, after a siege lasting over a year from July 1584 until August 1585. The city of Antwerp was the focal point of the Protestant-dominated Dutch Revolt, but was forced to surrender to the Spanish forces under the command of Alessandro Farnese.', 1584, 7, NULL, 1585, 8, 17, 'month', 'July 1584 – 17 August 1585', 53, 'https://en.wikipedia.org/wiki/Fall_of_Antwerp'),
  ('Q1392', 'Battle of Nieuwpoort', 'The Battle of Nieuwpoort (also known as the Battle of the Dunes) was fought on 2 July 1600 during the Eighty Years War and the Anglo-Spanish war in the dunes near Nieuwpoort. A Dutch army met a Spanish force head-on which, although their left flank nearly broke, were able to assail them with both infantry and cavalry.', 1600, 7, 2, NULL, NULL, NULL, 'day', '2 July 1600', 56, 'https://en.wikipedia.org/wiki/Battle_of_Nieuwpoort'),
  ('Q1783252', 'Battle of Seneffe', 'The Battle of Seneffe, 11 August 1674, took place during the Franco-Dutch War, near Seneffe in Belgium, then part of the Spanish Netherlands. A French army commanded by Condé confronted a combined Dutch, Imperial, and Spanish force under William of Orange.', 1674, 8, 11, NULL, NULL, NULL, 'day', '11 August 1674', 57, 'https://en.wikipedia.org/wiki/Battle_of_Seneffe'),
  ('Q1612417', 'Battle of Fleurus', 'The Battle of Fleurus, fought on 1 July 1690 near Fleurus, then part of the Spanish Netherlands, now in modern Belgium, was a major engagement of the Nine Years'' War. A French army led by Marshall Luxembourg defeated an Allied force under Waldeck.', 1690, 7, 1, NULL, NULL, NULL, 'day', '1 July 1690', 56, 'https://en.wikipedia.org/wiki/Battle_of_Fleurus_(1690)'),
  ('Q1636652', 'Battle of Steenkerque', 'The Battle of Steenkerque was fought on 3 August 1692, during the Nine Years'' War, near Steenkerque in Belgium, then part of the Spanish Netherlands. A French force under Marshal François-Henri de Montmorency, duc de Luxembourg, repulsed a surprise attack by an Allied army led by William of Orange.', 1692, 8, 3, NULL, NULL, NULL, 'day', '3 August 1692', 52, 'https://en.wikipedia.org/wiki/Battle_of_Steenkerque'),
  ('Q1767332', 'Battle of Landen', 'The Battle of Landen, also known as Battle of Neerwinden took place on 29 July 1693, during the Nine Years'' War near Landen, then in the Spanish Netherlands, now part of Belgium. A French army under Marshal Luxembourg defeated an Allied force led by William III. By 1693, all combatants were struggling with the financial and material costs of the conflict.', 1693, 7, 29, NULL, NULL, NULL, 'day', '29 July 1693', 57, 'https://en.wikipedia.org/wiki/Battle_of_Landen'),
  ('Q1195263', 'Battle of Ekeren', 'The Battle of Ekeren, which took place on 30 June 1703, was a battle of the War of the Spanish Succession. A Bourbon army of around 24,000 men, consisting of troops from France, Spain and Cologne, surrounded a smaller Dutch force of 12,000 men, which however managed to break out and retire to safety.', 1703, 6, 30, NULL, NULL, NULL, 'day', '30 June 1703', 53, 'https://en.wikipedia.org/wiki/Battle_of_Ekeren'),
  ('Q161325', 'Battle of Ramillies', 'The Battle of Ramillies, fought on 23 May 1706, was a battle of the War of the Spanish Succession. For the Grand Alliance – Austria, England, and the Dutch Republic – the battle had followed an indecisive campaign against the Bourbon armies of King Louis XIV of France in 1705.', 1706, 5, 23, NULL, NULL, NULL, 'day', '23 May 1706', 62, 'https://en.wikipedia.org/wiki/Battle_of_Ramillies'),
  ('Q316139', 'Battle of Oudenarde', 'The Battle of Oudenarde, also known as the Battle of Oudenaarde, was a major engagement of the War of the Spanish Succession, pitting an Anglo-Dutch force consisting of eighty thousand men under the command of the Duke of Marlborough, Lord Overkirk and Prince Eugene of Savoy against a French force of eighty-five thousand men under the command of the Duc de Bourgogne and the Duc de Vendôme, the battle resulting in a great victory for the Grand Alliance. The battle was fought near the city of Oudenaarde, at the time part of the Spanish Netherlands, on 11 July 1708.', 1708, 7, 11, NULL, NULL, NULL, 'day', '11 July 1708', 62, 'https://en.wikipedia.org/wiki/Battle_of_Oudenarde'),
  ('Q569953', 'Battle of Fontenoy', 'The Battle of Fontenoy was fought on 11 May 1745 near Tournai in the Austrian Netherlands during the War of the Austrian Succession. A French army of 50,000 men under Marshal General Maurice de Saxe defeated a Pragmatic Army of 50,000 British, Hanoverian, Dutch and Austrian troops under Captain-general William Augustus, Duke of Cumberland.', 1745, 5, 11, NULL, NULL, NULL, 'day', '11 May 1745', 66, 'https://en.wikipedia.org/wiki/Battle_of_Fontenoy'),
  ('Q32493', 'Battle of Rocoux', 'The Battle of Rocoux took place on 11 October 1746 during the War of the Austrian Succession, near Rocourt, Liège in Belgium. It was fought between a French army under Marshal Saxe and a combined British, Dutch, German and Austrian force led by Charles of Lorraine, Earl Ligonier and Prince Waldeck.', 1746, 10, 11, NULL, NULL, NULL, 'day', '11 October 1746', 57, 'https://en.wikipedia.org/wiki/Battle_of_Rocoux'),
  ('Q696699', 'Battle of Lauffeld', 'The Battle of Lauffeld took place on 2 July 1747, during the War of the Austrian Succession. Fought between the towns of Tongeren in modern Belgium, and the Dutch city of Maastricht, a French army of 136,000 under Marshal Saxe defeated a Pragmatic Army of 100,000, led by the Duke of Cumberland.', 1747, 7, 2, NULL, NULL, NULL, 'day', '2 July 1747', 56, 'https://en.wikipedia.org/wiki/Battle_of_Lauffeld'),
  ('Q855271', 'Battle of Jemappes', 'The Battle of Jemappes (6 November 1792) took place near the town of Jemappes in Hainaut, Austrian Netherlands (now Belgium), near Mons during the War of the First Coalition, part of the French Revolutionary Wars. One of the first major offensive battles of the war, it was a victory for the armies of the infant French Republic, and saw the French Armée du Nord, which included many inexperienced volunteers, defeat a substantially smaller regular Austrian army.', 1792, 11, 6, NULL, NULL, NULL, 'day', '6 November 1792', 61, 'https://en.wikipedia.org/wiki/Battle_of_Jemappes'),
  ('Q1085392', 'Battle of Neerwinden', 'The Battle of Neerwinden (18 March 1793) saw a Republican French army led by Charles François Dumouriez attack a Coalition army commanded by Prince Josias of Saxe-Coburg-Saalfeld. The Coalition army of the Habsburg monarchy together with a small contingent of allied Dutch Republic troops repulsed all French assaults after bitter fighting and Dumouriez conceded defeat, withdrawing from the field.', 1793, 3, 18, NULL, NULL, NULL, 'day', '18 March 1793', 58, 'https://en.wikipedia.org/wiki/Battle_of_Neerwinden_(1793)'),
  ('Q678227', 'Battle of Fleurus', 'The Battle of Fleurus was fought on 26 June 1794 during the War of the First Coalition between the French Revolutionary Army under Jean-Baptiste Jourdan and an Austro-Dutch army commanded by Prince Josias of Coburg. In what was the most significant battle of the Low Countries theatre of the War of the First Coalition, Jourdan''s army was able to concentrate its forces and defeat Coburg and his troops.', 1794, 6, 26, NULL, NULL, NULL, 'day', '26 June 1794', 64, 'https://en.wikipedia.org/wiki/Battle_of_Fleurus_(1794)'),
  ('Q1324198', 'Treaty of Ghent', 'The Treaty of Ghent (8 Stat. 218) was the peace treaty that ended the War of 1812 between the United States and the United Kingdom.', 1814, 12, 24, NULL, NULL, NULL, 'day', '24 December 1814', 66, 'https://en.wikipedia.org/wiki/Treaty_of_Ghent'),
  ('Q48314', 'Battle of Waterloo', 'The Battle of Waterloo was fought on Sunday 18 June 1815, near Waterloo (then in the United Kingdom of the Netherlands, now in Belgium), being the last engagement with Napoleon I. The French Imperial Army under the command of Napoleon I was defeated by two armies of the Seventh Coalition. One was a British-led force with units from the United Kingdom, the Netherlands, Hanover, Brunswick, and Nassau, under the command of Field Marshal Arthur Wellesley, Duke of Wellington.', 1815, 6, 18, NULL, NULL, NULL, 'day', '18 June 1815', 86, 'https://en.wikipedia.org/wiki/Battle_of_Waterloo'),
  ('Q705936', 'Battle of Quatre Bras', 'The Battle of Quatre Bras was fought on 16 June 1815, as a preliminary engagement to the decisive Battle of Waterloo that occurred two days later. The battle took place near the strategic crossroads of Quatre Bras and was contested between elements of the Duke of Wellington''s Anglo-allied army and the left wing of Napoleon Bonaparte''s French Armée du Nord under Marshal Michel Ney.', 1815, 6, 16, NULL, NULL, NULL, 'day', '16 June 1815', 61, 'https://en.wikipedia.org/wiki/Battle_of_Quatre_Bras'),
  ('Q855429', 'Battle of Ligny', 'The Battle of Ligny, in which French troops of the Armée du Nord under the command of Napoleon I defeated part of a Prussian army under Field Marshal Blücher, was fought on 16 June 1815 near Ligny in what is now Belgium. The result was a tactical victory for the French, but the bulk of the Prussian army survived the battle in good order, was reinforced by Prussian troops who had not fought at Ligny, and played a role two days later at the Battle of Waterloo.', 1815, 6, 16, NULL, NULL, NULL, 'day', '16 June 1815', 63, 'https://en.wikipedia.org/wiki/Battle_of_Ligny'),
  ('Q920107', 'Battle of Wavre', 'The Battle of Wavre was the final major military action of the Hundred Days campaign and the Napoleonic Wars. It was fought on 18–19 June 1815 between the Prussian rearguard, consisting of the Prussian III Corps under the command of General Johann von Thielmann (whose chief-of-staff was Carl von Clausewitz) and three corps of the French army under the command of Marshal Grouchy.', 1815, 6, 18, 1815, 6, 19, 'day', '18 June 1815 – 19 June 1815', 56, 'https://en.wikipedia.org/wiki/Battle_of_Wavre'),
  ('Q223933', 'Belgian Revolution', 'The Belgian Revolution (French: Révolution belge, Dutch: Belgische Revolutie/opstand/omwenteling) was a conflict which led to the secession of the southern provinces (mainly the former Southern Netherlands) from the United Kingdom of the Netherlands and the establishment of an independent Kingdom of Belgium. The people of the south were mainly Flemings and Walloons.', 1831, 7, 21, 1831, 7, 21, 'day', '21 July 1831', 76, 'https://en.wikipedia.org/wiki/Belgian_Revolution'),
  ('Q1160895', 'Treaty of London', 'The Treaty of London of 1839, was signed on 19 April 1839 between the major European powers, the United Kingdom of the Netherlands, and the Kingdom of Belgium. It was a direct follow-up to the 1831 Treaty of the XVIII Articles, which the Netherlands had refused to sign, and the result of negotiations at the London Conference of 1838–1839 which sought to maintain the Concert of Europe.', 1839, 4, 19, NULL, NULL, NULL, 'day', '19 April 1839', 71, 'https://en.wikipedia.org/wiki/Treaty_of_London_(1839)'),
  ('Q426099', 'Siege of Antwerp', 'The siege of Antwerp was an engagement between the German and the Belgian, British and French armies around the fortified city of Antwerp during the First World War. German troops besieged a garrison of Belgian fortress troops, the Belgian field army and the British Royal Naval Division in the Antwerp area, after the German invasion of Belgium in August 1914.', 1914, NULL, NULL, 1914, 10, 10, 'year', '1914', 64, 'https://en.wikipedia.org/wiki/Siege_of_Antwerp_(1914)'),
  ('Q671594', 'Battle of Liège', 'The Battle of Liège (5–16 August 1914) was the opening engagement of the German invasion of Belgium and the first battle of the First World War. The city of Liège was protected by a ring of modern fortresses, one of several fortified cities intended to delay an invasion for troops from the powers guaranteeing Belgian neutrality to mobilise and join the Belgian Army in the expulsion of the invader.', 1914, 8, 4, 1914, 8, 16, 'day', '4 August 1914 – 16 August 1914', 71, 'https://en.wikipedia.org/wiki/Battle_of_Li%C3%A8ge'),
  ('Q687572', 'Battle of the Frontiers', 'The Battle of the Frontiers (French: Bataille des Frontières; German: Grenzschlachten; Dutch: Slag der Grenzen) comprised battles fought along the eastern frontier of France and in southern Belgium, shortly after the outbreak of the First World War. The battles resolved the military strategies of the French Chief of Staff General Joseph Joffre with Plan XVII and an offensive adaptation of the German Aufmarsch II deployment plan by Helmuth von Moltke the Younger.', 1914, 9, 6, 1919, 9, 13, 'day', '6 September 1914 – 13 September 1919', 65, 'https://en.wikipedia.org/wiki/Battle_of_the_Frontiers'),
  ('Q792340', 'German invasion of Belgium (1914)', 'The German invasion of Belgium began on 4 August 1914 during the first World War. On 24 July, the Belgian government had announced that if war came it would uphold its neutrality.', 1914, 8, 4, 1914, 10, 31, 'day', '4 August 1914 – 31 October 1914', 57, 'https://en.wikipedia.org/wiki/German_invasion_of_Belgium_(1914)'),
  ('Q853976', 'First Battle of Ypres', 'The First Battle of Ypres (French: Première Bataille des Flandres, German: Erste Flandernschlacht, 19 October – 22 November 1914) was a battle of the First World War, fought on the Western Front around Ypres, in West Flanders, Belgium. The battle was part of the First Battle of Flanders, in which German, French, Belgian armies and the British Expeditionary Force (BEF) fought from Arras in France to Nieuwpoort (Nieuport) on the Belgian coast, from 10 October to mid-November.', 1914, 10, 19, 1914, 11, 22, 'day', '19 October 1914 – 22 November 1914', 69, 'https://en.wikipedia.org/wiki/First_Battle_of_Ypres'),
  ('Q860150', 'Battle of Charleroi', 'The Battle of Charleroi (French: Bataille de Charleroi) or the Battle of the Sambre, was fought on 21 August 1914, by the French Fifth Army and the German 2nd and 3rd armies, during the Battle of the Frontiers. The French were planning an attack across the Sambre River, when the Germans attacked first, forced back the French from the river and nearly cut off the French retreat by crossing the Meuse River around Dinant and getting behind the French right flank.', 1914, 8, 21, 1914, 8, 23, 'day', '21 August 1914 – 23 August 1914', 62, 'https://en.wikipedia.org/wiki/Battle_of_Charleroi'),
  ('Q1417205', 'Battle of Mons', 'The Battle of Mons, or the First Battle of Mons to differentiate it from another battle later in the war, was the first big engagement of the British Expeditionary Force (BEF) in the First World War. It was a subsidiary action of the Battle of the Frontiers, in which the Allies clashed with the German Army on the French–German frontier.', 1914, 8, 23, NULL, NULL, NULL, 'day', '23 August 1914', 61, 'https://en.wikipedia.org/wiki/Battle_of_Mons'),
  ('Q1497933', 'Battle of Haelen', 'The Battle of Halen (German: Gefecht bei Halen), also known as the Battle of the Silver Helmets (Dutch: Slag der Zilveren Helmen; French: Bataille des casques d''argent) because of the many cavalry helmets left behind on the battlefield by the German cuirassiers, took place on 12 August 1914 at the beginning of the First World War, between German forces led by Georg von der Marwitz and Belgian troops led by Léon De Witte. The name of the battle alludes to the Battle of the Golden Spurs in 1302, where 500 pairs of golden spurs were recovered from the battlefield.', 1914, 8, 12, NULL, NULL, NULL, 'day', '12 August 1914', 57, 'https://en.wikipedia.org/wiki/Battle_of_Halen'),
  ('Q1653331', 'Battle of the Yser', 'The Battle of the Yser was a battle of the First World War that took place in October 1914 between the towns of Nieuwpoort and Diksmuide, along a 35 km (22 mi) stretch of the Yser River and the Yperlee Canal, in Belgium. The front line was held by a large Belgian force, which halted the German advance in a costly defensive battle.', 1914, 10, 16, 1914, 10, 31, 'day', '16 October 1914 – 31 October 1914', 59, 'https://en.wikipedia.org/wiki/Battle_of_the_Yser'),
  ('Q233219', 'Second Battle of Ypres', 'The Second Battle of Ypres was fought from 22 April to 25 May 1915, during the First World War, for control of the tactically valuable high ground to the east and the south of the Flemish town of Ypres, in western Belgium. The First Battle of Ypres had been fought the previous autumn.', 1915, 4, 21, 1915, 5, 25, 'day', '21 April 1915 – 25 May 1915', 69, 'https://en.wikipedia.org/wiki/Second_Battle_of_Ypres'),
  ('Q426227', 'Third Battle of Ypres', 'The Third Battle of Ypres (German: Dritte Flandernschlacht; French: Troisième Bataille des Flandres; Dutch: Derde Slag om Ieper), also known as the Battle of Passchendaele ( PASH-ən-dayl), was a campaign of the First World War, fought by the Allies against the German Empire. The battle took place on the Western Front, from July to November 1917, for control of the ridges south and east of the Belgian city of Ypres in West Flanders, as part of a strategy decided by the Entente at conferences in November 1916 and May 1917.', 1917, 7, 31, 1917, 11, 10, 'day', '31 July 1917 – 10 November 1917', 73, 'https://en.wikipedia.org/wiki/Battle_of_Passchendaele'),
  ('Q1144824', 'Battle of Messines', 'The Battle of Messines (7–14 June 1917) was an attack by the British Second Army (General Sir Herbert Plumer), on the Western Front, near the village of Messines (Dutch: Mesen) in West Flanders, Belgium, during the First World War. The Nivelle Offensive in April and May had failed to achieve its more grandiose aims, had led to the demoralisation of French troops and confounded the Anglo-French strategy for 1917.', 1917, 6, 7, 1917, 6, 14, 'day', '7 June 1917 – 14 June 1917', 64, 'https://en.wikipedia.org/wiki/Battle_of_Messines_(1917)'),
  ('Q700864', 'Zeebrugge Raid', 'The Zeebrugge Raid (Dutch: Aanval op de haven van Zeebrugge; French: Raid sur Zeebruges) on 23 April 1918, was an attempt by the Royal Navy to block the Belgian port of Bruges-Zeebrugge. The British intended to sink obsolete ships in the canal entrance, to prevent German vessels from leaving port.', 1918, 4, 23, NULL, NULL, NULL, 'day', '23 April 1918', 53, 'https://en.wikipedia.org/wiki/Zeebrugge_Raid'),
  ('Q750567', 'Spring Offensive', 'The German spring offensive, also known as Kaiserschlacht ("Emperor''s Battle") or the Ludendorff offensive, was a series of German attacks along the Western Front during the First World War, beginning on 21 March 1918. Following the American entry into the war in April 1917, the Germans decided that their only remaining chance of victory was to defeat the Allies before the United States could ship soldiers across the Atlantic and fully deploy its resources.', 1918, 3, 21, 1918, 7, 18, 'day', '21 March 1918 – 18 July 1918', 70, 'https://en.wikipedia.org/wiki/German_spring_offensive'),
  ('Q1088364', 'Battle of the Lys', 'The Battle of the Lys, also known as the Fourth Battle of Ypres, was fought from 7 to 29 April 1918 and was part of the German spring offensive in Flanders during the First World War. It was originally planned by General Erich Ludendorff as Operation George but was reduced to Operation Georgette, with the objective of capturing Ypres, forcing the British forces back to the Channel ports and out of the war.', 1918, 4, 7, 1918, 4, 29, 'day', '7 April 1918 – 29 April 1918', 56, 'https://en.wikipedia.org/wiki/Battle_of_the_Lys_(1918)'),
  ('Q151340', 'Battle of France', 'The Battle of France (French: Bataille de France, 10 May – 25 June 1940), also known as the Fall of France, was the German invasion of the Low Countries (Belgium, Luxembourg and the Netherlands) and France during the Second World War. The plan for the invasion of the Low Countries and France was called Fall Gelb (Case Yellow or the Manstein plan).', 1940, 5, 10, 1940, 6, 25, 'day', '10 May 1940 – 25 June 1940', 82, 'https://en.wikipedia.org/wiki/Battle_of_France'),
  ('Q452157', 'Mechelen incident', 'The Mechelen incident of 10 January 1940, also known as the Mechelen affair, took place in Belgium during the Phoney War in the first stages of World War II. A German aircraft with an officer on board carrying the plans for Fall Gelb (Case Yellow), the German attack on the Low Countries, crash-landed in neutral Belgium near Vucht in the modern-day municipality of Maasmechelen (Mechelen-aan-de-Maas) within the Province of Limburg. This prompted an immediate crisis in the Low Countries and amidst the French and British authorities, whom the Belgians notified of their discovery; however, the…', 1940, 1, 10, NULL, NULL, NULL, 'day', '10 January 1940', 53, 'https://en.wikipedia.org/wiki/Mechelen_incident'),
  ('Q697625', 'German invasion of Belgium', 'The invasion of Belgium or Belgian campaign (10–28 May 1940), formed part of the larger Battle of France, an offensive campaign by Germany during the Second World War. It took place over 18 days in May 1940 and ended with the German occupation of Belgium following the surrender of the Belgian Army.', 1940, 5, 10, 1940, 5, 28, 'day', '10 May 1940 – 28 May 1940', 70, 'https://en.wikipedia.org/wiki/German_invasion_of_Belgium_(1940)'),
  ('Q714265', 'Battle of Gembloux', 'The Battle of Gembloux (or Battle of the Gembloux Gap) was fought between French and German forces in May 1940 during the Second World War. On 10 May 1940, The Wehrmacht, invaded Luxembourg, The Netherlands and Belgium under the operational plan Fall Gelb (Case Yellow).', 1940, 5, 14, 1940, 5, 15, 'day', '14 May 1940 – 15 May 1940', 55, 'https://en.wikipedia.org/wiki/Battle_of_Gembloux_(1940)'),
  ('Q714288', 'Battle of Fort Eben-Emael', 'The Battle of Fort Ében-Émael was a battle between Belgian and German forces that took place between 10 May and 11 May 1940, and was part of the Battle of Belgium and Fall Gelb, the German invasion of the Low Countries and France. An assault force of German paratroopers, Fallschirmjäger, was tasked with assaulting and suppressing Fort Ében-Émael, a Belgian fortress whose strategic position and strong artillery emplacements dominated several important bridges over the Albert Canal.', 1940, 5, 10, 1940, 5, 11, 'day', '10 May 1940 – 11 May 1940', 61, 'https://en.wikipedia.org/wiki/Battle_of_Fort_%C3%89ben-%C3%89mael'),
  ('Q2032618', 'Battle of Hannut', 'The Battle of Hannut was a Second World War battle fought during the Battle of Belgium which took place between 12 and 14 May 1940 at Hannut in Belgium. It was the largest tank battle in the campaign.', 1940, 5, 12, 1940, 5, 14, 'day', '12 May 1940 – 14 May 1940', 58, 'https://en.wikipedia.org/wiki/Battle_of_Hannut'),
  ('Q151018', 'Battle of the Bulge', 'The Battle of the Bulge, also known as the Ardennes Offensive and referred to by the Germans as Unternehmen Wacht am Rhein (transl. Operation Watch on the Rhine), was an offensive campaign on the Western Front during the Second World War, taking place from 16 December 1944 to 25 January 1945. It was launched through the densely forested Ardennes region of eastern Belgium and northern Luxembourg and was intended to stop Allied use of the Belgian port of Antwerp and to split the Allied lines, allowing the Germans to encircle and destroy each of the four Allied armies and force the western…', 1944, 12, 16, 1945, 1, 25, 'day', '16 December 1944 – 25 January 1945', 79, 'https://en.wikipedia.org/wiki/Battle_of_the_Bulge'),
  ('Q162228', 'Malmedy massacre', 'The Malmedy massacre was a German war crime committed by soldiers of the Waffen-SS on 17 December 1944 at the Baugnez crossroads near the city of Malmedy, Belgium, during the Battle of the Bulge (16 December 1944 – 25 January 1945). German soldiers under the command of Joachim Peiper (Kampfgruppe Peiper) summarily executed 84 U.S. Army prisoners of war (POWs) who had surrendered to them following a brief skirmish.', 1944, 12, 17, NULL, NULL, NULL, 'day', '17 December 1944', 67, 'https://en.wikipedia.org/wiki/Malmedy_massacre'),
  ('Q167002', 'Operation Greif', 'Operation Greif (English: Griffin; German: Unternehmen Greif) was a special operation commanded by Waffen-SS commando Otto Skorzeny during the Battle of the Bulge in World War II. The operation was the brainchild of Adolf Hitler, and its purpose was to capture one or more of the bridges over the Meuse River before they could be destroyed. German soldiers, wearing captured British and U.S. Army uniforms and using captured Allied vehicles, were to cause confusion in the rear of the Allied lines.', 1944, 12, 16, NULL, NULL, NULL, 'day', '16 December 1944', 58, 'https://en.wikipedia.org/wiki/Operation_Greif'),
  ('Q697022', 'Battle of the Scheldt', 'The Battle of the Scheldt in World War II was a series of military operations to open up the Scheldt river between Antwerp and the North Sea for shipping, so that Antwerp''s port could be used to supply the Allies in north-west Europe. The operations were carried out by the First Canadian Army, with assistance from Polish and British units which had been attached.', 1944, 10, 2, 1944, 11, 8, 'day', '2 October 1944 – 8 November 1944', 65, 'https://en.wikipedia.org/wiki/Battle_of_the_Scheldt'),
  ('Q708181', 'Siege of Bastogne', 'The siege of Bastogne (French pronunciation: [bas.tɔɲ] ) was an engagement in December 1944 between American and German forces at the Belgian town of Bastogne, as part of the larger Battle of the Bulge. The goal of the German offensive was the harbor at Antwerp.', 1944, 12, 20, 1944, 12, 27, 'day', '20 December 1944 – 27 December 1944', 58, 'https://en.wikipedia.org/wiki/Siege_of_Bastogne'),
  ('Q835881', 'Operation Bodenplatte', 'Operation Bodenplatte (German: [ˈboːdn̩ˌplatə]; "Baseplate"), launched on 1 January 1945, was an attempt by the German Luftwaffe to cripple Allied air forces in the Low Countries during the Second World War. The goal of Bodenplatte was to gain air superiority during the stagnant stage of the Battle of the Bulge so that the German Army and Waffen-SS forces could resume their advance.', 1945, 1, 1, NULL, NULL, NULL, 'day', '1 January 1945', 64, 'https://en.wikipedia.org/wiki/Operation_Bodenplatte'),
  ('Q845737', 'Treaty of Brussels', 'The Treaty of Brussels, also referred to as the Brussels Pact, was the founding treaty of the Western Union (WU) between 1948 and 1954, when it was amended as the Modified Brussels Treaty (MTB) and served as the founding treaty of the Western European Union (WEU) until its termination in 2010. The treaty provided for the organisation of military, economic, social and cultural cooperation among member states as well as a mutual defence clause.', 1948, 3, 17, NULL, NULL, NULL, 'day', '17 March 1948', 68, 'https://en.wikipedia.org/wiki/Treaty_of_Brussels'),
  ('Q504934', 'North Sea flood of 1953', 'The North Sea flood of 1953, also known as the Big Flood or East Coast Flood (in England) or as the Flood Disaster (Dutch: Watersnoodramp), was a flood caused by a heavy storm surge in the North Sea that struck low-lying coastal areas of the Netherlands, Belgium, and the United Kingdom. More than 2,000 people were killed on land and hundreds more at sea.', 1953, 1, 31, 1953, 2, 1, 'day', '31 January 1953 – 1 February 1953', 67, 'https://en.wikipedia.org/wiki/North_Sea_flood_of_1953'),
  ('Q1575474', 'Sabena Flight 548', 'Sabena Flight 548 was a scheduled international passenger flight from Idlewild Airport in New York City to Brussels Airport in Belgium. On 15 February 1961, the Boeing 707 operating the flight crashed on approach to Brussels Airport, killing all 72 people on board and one person on the ground.', 1961, 2, 15, NULL, NULL, NULL, 'day', '15 February 1961', 56, 'https://en.wikipedia.org/wiki/Sabena_Flight_548'),
  ('Q473893', '2011 Liège attack', 'On 13 December 2011, a murder–suicide attack took place in the city of Liège in the Wallonia region of Belgium. The attacker, 33-year-old Nordine Amrani, threw grenades and fired an FN FAL rifle at civilians on the Place Saint-Lambert, the city''s main square.', 2011, 12, 13, NULL, NULL, NULL, 'day', '13 December 2011', 61, 'https://en.wikipedia.org/wiki/2011_Li%C3%A8ge_attack'),
  ('Q1377817', 'European Fiscal Compact', 'The Treaty on Stability, Coordination and Governance in the Economic and Monetary Union; also referred to as TSCG, or more plainly the Fiscal Stability Treaty is an intergovernmental treaty introduced as a new stricter version of the Stability and Growth Pact, signed on 2 March 2012 by all member states of the European Union (EU), except the Czech Republic and the United Kingdom. The treaty entered into force on 1 January 2013 for the 16 states which completed ratification prior to this date.', 2012, 3, 2, NULL, NULL, NULL, 'day', '2 March 2012', 62, 'https://en.wikipedia.org/wiki/European_Fiscal_Compact'),
  ('Q23365300', '2016 Brussels bombings', 'On 22 March 2016, two coordinated terrorist attacks in and close to Brussels, Belgium, were carried out by the Islamic State (IS). Two suicide bombers detonated bombs at Brussels Airport in Zaventem just outside Brussels, and a third detonated a bomb on a train leaving Maelbeek/Maalbeek metro station in the city''s European Quarter.', 2016, 3, 22, NULL, NULL, NULL, 'day', '22 March 2016', 80, 'https://en.wikipedia.org/wiki/2016_Brussels_bombings'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q107529288', '2021 European floods', 'In July 2021, several European countries were affected by severe floods. Some were catastrophic, causing deaths and widespread damage.', 2021, NULL, NULL, 2021, 7, 25, 'year', '2021', 73, 'https://en.wikipedia.org/wiki/2021_European_floods');
